CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, title TEXT NOT NULL, url TEXT NOT NULL UNIQUE, source TEXT NOT NULL DEFAULT 'manual', description TEXT NOT NULL DEFAULT '', score INTEGER NOT NULL DEFAULT 0, verified_paid INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'new', draft TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY AUTOINCREMENT, job_id TEXT, event TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')));
